import{_ as t,C as s,o as e,c as l,j as i,E as r,a as n,a3 as d}from"./chunks/framework.C6R8kWFE.js";const k=JSON.parse(`{"title":"2-hafta","description":"","frontmatter":{"title":"2-hafta","layout":"doc","sidebar":false,"aside":false,"outline":false,"kind":"hafta","hafta":{"sinf":{"name":"10-sinf (DevOps)","link":"/10-sinf-devops/"},"n":2,"bob":"I-bob · Operatsion tizimlar (Linux)","lessons":[{"g":4,"title":"Xizmatlar va jarayonlarni boshqarish (ps, top, kill, systemd)","lead":"Linux operatsion tizimi tomir urishi: jarayonlar monitoringi (ps, top), boshqaruv signallari (kill, nice) hamda doimiy ishlovchi xizmatlar (systemd/systemctl).","link":"/10-sinf-devops/hafta-02/dars-1","slide":"/slaydlar/10-sinf-devops/hafta-02/dars-1.html","test":"/slaydlar/10-sinf-devops/hafta-02/dars-1-test.html"},{"g":5,"title":"Disklar, fayl tizimlari va paket menejerlari (APT, DNF)","lead":"Linuxda xotira boshqaruvi: disklar va bo'limlar arxitekturasi (df, du, mount), zamonaviy fayl tizimlari hamda xavfsiz dastur o'rnatish tizimi (APT/DNF).","link":"/10-sinf-devops/hafta-02/dars-2","slide":"/slaydlar/10-sinf-devops/hafta-02/dars-2.html","test":"/slaydlar/10-sinf-devops/hafta-02/dars-2-test.html"},{"g":6,"title":"Git va versiya boshqaruvi tizimlariga kirish (Git asoslari)","lead":"Dasturiy ta'minotning vaqt mashinasi: Git versiya boshqaruvi, 3 ta hudud (Working, Staging, Repository), commitlar anatomiyasi va .gitignore sirlari.","link":"/10-sinf-devops/hafta-02/dars-3","slide":"/slaydlar/10-sinf-devops/hafta-02/dars-3.html","test":"/slaydlar/10-sinf-devops/hafta-02/dars-3-test.html"}],"test":"/slaydlar/10-sinf-devops/hafta-02/hafta-test.html"}},"headers":[],"relativePath":"10-sinf-devops/hafta-02/index.md","filePath":"10-sinf-devops/hafta-02/index.md"}`),c={name:"10-sinf-devops/hafta-02/index.md"},h={class:"blk"},m={id:"uyga-vazifa",tabindex:"-1"};function g(u,a,f,y,v,p){const o=s("Icon");return e(),l("div",null,[i("div",h,[i("h2",m,[r(o,{name:"house"}),a[0]||(a[0]=n(" Uyga vazifa ",-1)),a[1]||(a[1]=i("a",{class:"header-anchor",href:"#uyga-vazifa","aria-label":'Permalink to "<Icon name="house" /> Uyga vazifa"'},"​",-1))]),a[2]||(a[2]=d('<p>2-haftada jarayonlar (processes) va systemd xizmatlarini boshqarish, disklar va fayl tizimlari tahlili (df/du), paket menejerlari (APT) hamda Git versiya boshqaruvi tizimining poydevori (init, add, commit, .gitignore) o&#39;rganildi. Quyidagi vazifalar amaliy ko&#39;nikmalarni mustahkamlash uchun berilgan.</p><hr><h3 id="_4-dars-vazifasi-jarayonlar-va-xizmatlar" tabindex="-1">4-dars vazifasi: Jarayonlar va Xizmatlar <a class="header-anchor" href="#_4-dars-vazifasi-jarayonlar-va-xizmatlar" aria-label="Permalink to &quot;4-dars vazifasi: Jarayonlar va Xizmatlar&quot;">​</a></h3><ol><li>Terminalda <code>top</code> yoki <code>htop</code> dasturini oching. Tizimingizda umumiy nechta jarayon mavjudligi, ulardan nechtasi faol («running») holatda ekanini daftaringizga qayd eting.</li><li><code>sleep 400 &amp;</code> buyrug&#39;i yordamida yangi fon jarayonini ishga tushiring. <code>jobs</code> va <code>ps aux | grep sleep</code> buyruqlari yordamida uning PID raqamini aniqlang.</li><li>Aniqlangan PID raqami bo&#39;yicha <code>kill [PID]</code> buyrug&#39;i bilan ushbu jarayonni to&#39;xtating.</li><li><code>systemctl status cron</code> (yoki <code>crond</code>) buyrug&#39;ini bajarib, rejalashtiruvchi xizmatning faol holatini tekshiring. <em>(Kutiladigan vaqt: 25 daqiqa)</em></li></ol><hr><h3 id="_5-dars-vazifasi-disk-sarfi-va-paketlar" tabindex="-1">5-dars vazifasi: Disk sarfi va Paketlar <a class="header-anchor" href="#_5-dars-vazifasi-disk-sarfi-va-paketlar" aria-label="Permalink to &quot;5-dars vazifasi: Disk sarfi va Paketlar&quot;">​</a></h3><ol><li><code>df -h</code> buyrug&#39;ini bajaring va asosiy ildiz (<code>/</code>) bo&#39;limida qancha umumiy hajm, ishlatilgan hajm va bo&#39;sh joy qolganini aniqlang.</li><li>O&#39;z uy katalogingizdagi barcha papkalar hajmini <code>du -sh ~/* | sort -h</code> orqali saralangan holda ko&#39;ring va eng katta 3 ta papkani yozib oling.</li><li><code>sudo apt update</code> buyrug&#39;i orqali paketlar indeksini yangilang, so&#39;ngra <code>sudo apt install -y curl wget ncdu</code> buyruqlari bilan ushbu utilitalarni o&#39;rnating.</li><li><code>ncdu ~</code> dasturini ishga tushirib, interaktiv terminal orqali xotira taqsimotini tahlil qiling. <em>(Kutiladigan vaqt: 25 daqiqa)</em></li></ol><hr><h3 id="_6-dars-vazifasi-git-va-repozitoriya-asoslari" tabindex="-1">6-dars vazifasi: Git va Repozitoriya asoslari <a class="header-anchor" href="#_6-dars-vazifasi-git-va-repozitoriya-asoslari" aria-label="Permalink to &quot;6-dars vazifasi: Git va Repozitoriya asoslari&quot;">​</a></h3><ol><li>Uy katalogingizda <code>my_git_lab</code> nomli yangi papka oching va uni <code>git init</code> orqali Git omboriga aylantiring.</li><li>Repozitoriya ichida <code>app.py</code>, <code>README.md</code> va <code>database.log</code> fayllarini yarating.</li><li><code>.gitignore</code> faylini yaratib, uning ichiga <code>*.log</code> qoidasini yozing.</li><li><code>git status</code> orqali <code>database.log</code> ning e&#39;tiborsiz qoldirilganini tekshiring.</li><li>Qolgan fayllarni <code>git add .</code> qiling va <code>git commit -m &quot;feat: dastlabki fayllar yaratildi&quot;</code> izohi bilan birinchi commitni amalga oshiring.</li><li><code>README.md</code> fayliga bitta yangi qator qo&#39;shib, uni ikkinchi commit bilan tarixga saqlang (<code>git commit -m &quot;docs: README yangilandi&quot;</code>).</li><li><code>git log --oneline</code> natijasini daftaringizga ko&#39;chirib yozing. <em>(Kutiladigan vaqt: 25 daqiqa)</em></li></ol><hr>',11))])])}const z=t(c,[["render",g]]);export{k as __pageData,z as default};
